#include <climits>
#include <cstdio>

int main() {
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < 1 || n > 1000) return 1;
    long long max_count = 0;
    long long min_count = 0;
    for (int i = 0; i < n; i++) {
        long long value = 0;
        if (std::scanf("%lld", &value) != 1) return 1;
        if (value < INT_MIN || value > INT_MAX) return 1;
        if (value == INT_MAX) max_count++;
        if (value == INT_MIN) min_count++;
    }
    std::printf("max=%lld min=%lld\n", max_count, min_count);
    return 0;
}
